begin;
-- Synthetic identities exist only within this transaction. No emails or fixtures committed.
create temporary table financial_test_users(id uuid primary key);
insert into financial_test_users values(gen_random_uuid()),(gen_random_uuid());
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
 select id,'financial_'||id::text||'@uwo.ca',now(),jsonb_build_object('username','Fin_'||substr(replace(id::text,'-',''),1,12)) from financial_test_users;
grant select on financial_test_users to authenticated,service_role,anon;
create function pg_temp.ensure(v boolean,label text) returns void language plpgsql as $$ begin if v is not true then raise exception 'Financial test: %',label; end if; end; $$;
create function pg_temp.fail_with(statement text,expected text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if sqlstate=expected then return; end if; raise exception 'Unexpected SQLSTATE %, expected %',sqlstate,expected; end; raise exception 'Missing expected failure: %',expected; end; $$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',id,'role','authenticated')::text,true) from financial_test_users order by id limit 1;
select pg_temp.ensure(public.marketplace_financial_capabilities() = '{"paymentMethod":{"status":"unset","brand":null,"last4":null},"payoutAccount":{"status":"unset","institution":null,"last4":null}}','default unset/no fake metadata');
select pg_temp.fail_with('select * from marketplace_private.financial_capabilities','42501');
select pg_temp.fail_with(format('select public.marketplace_financial_capabilities_for_user(%L)',(select max(id::text)::uuid from financial_test_users)),'42501');
select pg_temp.fail_with(format('select public.marketplace_record_financial_capability(%L,''payout_account'',''ready'',''test_adapter'',''test_owner'',''test_instrument'',''Test Bank'',''6789'')',auth.uid()),'42501');
select pg_temp.fail_with(format('insert into marketplace_private.financial_capabilities(user_id,capability,status,provider_key,provider_owner_ref,provider_instrument_ref) values(%L,''payment_method'',''set'',''test_adapter'',''test_owner'',''test_instrument'')',auth.uid()),'42501');
select pg_temp.fail_with('update marketplace_private.financial_capabilities set status=''ready''','42501');
select pg_temp.fail_with('delete from marketplace_private.financial_capabilities','42501');
reset role;
set local role anon;
select pg_temp.fail_with('select public.marketplace_financial_capabilities()','42501');
select pg_temp.fail_with('select * from marketplace_private.financial_capabilities','42501');
select pg_temp.fail_with(format('select public.marketplace_record_financial_capability(%L,''payout_account'',''ready'',''test_adapter'',''test_owner'',''test_instrument'',''Test Bank'',''6789'')',(select min(id::text)::uuid from financial_test_users)),'42501');
reset role;
set local role service_role;
select public.marketplace_record_financial_capability((select min(id::text)::uuid from financial_test_users),'payment_method','set','test_adapter','test_owner','test_method','Test Brand','4242');
select public.marketplace_record_financial_capability((select min(id::text)::uuid from financial_test_users),'payout_account','ready','test_adapter','test_owner','test_account','Test Bank','6789');
select pg_temp.ensure(public.marketplace_financial_capabilities_for_user((select min(id::text)::uuid from financial_test_users))->'payoutAccount'->>'status'='ready','trusted mutation/read');
select pg_temp.fail_with(format('select public.marketplace_record_financial_capability(%L,''payment_method'',''ready'',''test_adapter'',''test_owner'',''test_method'',null,null)',(select min(id::text)::uuid from financial_test_users)),'23514');
select pg_temp.fail_with(format('select public.marketplace_record_financial_capability(%L,''payout_account'',''ready'',''test_adapter'',''test_owner'',''test_account'',''Test Bank'',''12345'')',(select min(id::text)::uuid from financial_test_users)),'23514');
select pg_temp.fail_with(format('select public.marketplace_record_financial_capability(%L,''payout_account'',''ready'',''test_adapter'',''test_owner'',''test_account'',''   '',null)',(select min(id::text)::uuid from financial_test_users)),'23514');
select pg_temp.fail_with(format('select public.marketplace_record_financial_capability(%L,''payout_account'',''ready'',''test_adapter'',''test_owner'',''test_account'',''Test 123456'',null)',(select min(id::text)::uuid from financial_test_users)),'23514');
select pg_temp.fail_with(format('select public.marketplace_record_financial_capability(%L,''payout_account'',''ready'',''test_adapter'',''test_owner'',''test_account'',null,null)',gen_random_uuid()),'23503');
reset role;
select pg_temp.ensure((select count(*)=2 from marketplace_private.financial_capabilities where user_id=(select min(id::text)::uuid from financial_test_users)),'one of each independent');
select pg_temp.fail_with(format('insert into marketplace_private.financial_capabilities select * from marketplace_private.financial_capabilities where user_id=%L and capability=''payment_method''',(select min(id::text)::uuid from financial_test_users)),'23505');
select pg_temp.fail_with(format('insert into marketplace_private.financial_capabilities select * from marketplace_private.financial_capabilities where user_id=%L and capability=''payout_account''',(select min(id::text)::uuid from financial_test_users)),'23505');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select min(id::text)::uuid from financial_test_users),'role','authenticated')::text,true);
select pg_temp.ensure(public.marketplace_financial_capabilities() = '{"paymentMethod":{"status":"set","brand":"Test Brand","last4":"4242"},"payoutAccount":{"status":"ready","institution":"Test Bank","last4":"6789"}}','own exact safe projection');
select set_config('request.jwt.claims',jsonb_build_object('sub',(select max(id::text)::uuid from financial_test_users),'role','authenticated')::text,true);
select pg_temp.ensure(public.marketplace_financial_capabilities()->'paymentMethod'->>'status'='unset','cross-user projection isolation');
reset role;
set local role service_role;
select public.marketplace_record_financial_capability((select min(id::text)::uuid from financial_test_users),'payment_method','needs_attention','test_adapter','test_owner','test_method','Test Brand','4242');
select public.marketplace_record_financial_capability((select min(id::text)::uuid from financial_test_users),'payout_account','needs_attention','test_adapter','test_owner','test_account','Test Bank','6789');
select pg_temp.ensure(public.marketplace_financial_capabilities_for_user((select min(id::text)::uuid from financial_test_users))->'paymentMethod'->>'status'='needs_attention','trusted attention');
select public.marketplace_record_financial_capability((select min(id::text)::uuid from financial_test_users),'payment_method','unset',null,null,null,null,null);
select pg_temp.ensure(public.marketplace_financial_capabilities_for_user((select min(id::text)::uuid from financial_test_users))->'paymentMethod'->>'status'='unset','clear independent');
reset role;
delete from auth.users where id in(select id from financial_test_users);
select pg_temp.ensure(not exists(select 1 from marketplace_private.financial_capabilities where user_id in(select id from financial_test_users)),'profile lifecycle cascade');
rollback;
